  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import { ListTodo, MessageSquare, Terminal } from "lucide-react";
 20→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 21→import { condenseMessages } from "@/lib/condense-messages";
 22→import { StatusBar } from "./status-bar";
 23→import { AgentSummary } from "./agent-summary";
 24→import { Message } from "./message";
 25→import { ControlRequest } from "./control-request";
 26→import { UserQuestion } from "./user-question";
 27→import { CondensedToolGroup } from "./condensed-tool-group";
 28→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 29→import { Button } from "@/components/ui/button";
 30→
 31→export function Chat({
 32→  connected,
 33→  loading,
 34→  status,
 35→  messages,
 36→  rawMessages,
 37→  onSendMessage,
 38→  onSpawnAgent,
 39→  onRespondToControl,
 40→  onRespondToUserQuestion,
 41→  onClearHistory,
 42→  showTasks,
 43→  onToggleTasks,
 44→  onToggleSidebar,
 45→}: {
 46→  connected: boolean;
 47→  loading?: boolean;
 48→  status: AgentStatus;
 49→  messages: ChatMessage[];
 50→  rawMessages: ClaudeMessage[];
 51→  onSendMessage: (content: string) => void;
 52→  onSpawnAgent: (prompt: string) => void;
 53→  onRespondToControl: (requestId: string, allow: boolean) => void;
 54→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 55→  onClearHistory?: () => void;
 56→  showTasks?: boolean;
 57→  onToggleTasks?: () => void;
 58→  onToggleSidebar?: () => void;
 59→}) {
 60→  const [input, setInput] = useState("");
 61→  const [showRaw, setShowRaw] = useState(false);
 62→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 63→  const [slashQuery, setSlashQuery] = useState("");
 64→  const [slashHighlight, setSlashHighlight] = useState(0);
 65→  const scrollRef = useRef<HTMLDivElement>(null);
 66→  const inputRef = useRef<HTMLInputElement>(null);
 67→
 68→  useEffect(() => {
 69→    scrollRef.current?.scrollTo({
 70→      top: scrollRef.current.scrollHeight,
 71→      behavior: "smooth",
 72→    });
 73→  }, [messages, rawMessages, showRaw]);
 74→
 75→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 76→  const isActive = status === "connected" || status === "thinking";
 77→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 78→
 79→  function handleSubmit(e: React.FormEvent) {
 80→    e.preventDefault();
 81→    const trimmed = input.trim();
 82→    if (!trimmed) return;
 83→
 84→    if (isActive) {
 85→      onSendMessage(trimmed);
 86→    } else {
 87→      onSpawnAgent(trimmed);
 88→    }
 89→    setInput("");
 90→    setShowSlashMenu(false);
 91→  }
 92→
 93→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
 94→    const value = e.target.value;
 95→    setInput(value);
 96→
 97→    if (value.startsWith("/")) {
 98→      setShowSlashMenu(true);
 99→      setSlashQuery(value.slice(1));
100→      setSlashHighlight(0);
101→    } else {
102→      setShowSlashMenu(false);
103→      setSlashQuery("");
104→    }
105→  }
106→
107→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
108→    if (!showSlashMenu) return;
109→    const filtered = filterCommands(slashQuery);
110→    if (filtered.length === 0) return;
111→
112→    if (e.key === "ArrowDown") {
113→      e.preventDefault();
114→      setSlashHighlight((i) => (i + 1) % filtered.length);
115→    } else if (e.key === "ArrowUp") {
116→      e.preventDefault();
117→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
118→    } else if (e.key === "Enter") {
119→      e.preventDefault();
120→      handleCommandSelect(filtered[slashHighlight]);
121→    } else if (e.key === "Escape") {
122→      e.preventDefault();
123→      setShowSlashMenu(false);
124→    } else if (e.key === "Tab") {
125→      e.preventDefault();
126→      setInput(`/${filtered[slashHighlight].name} `);
127→      setShowSlashMenu(false);
128→    }
129→  }
130→
131→  function handleCommandSelect(command: SlashCommand) {
132→    setShowSlashMenu(false);
133→    setSlashQuery("");
134→    setInput("");
135→
136→    if (command.clientSide) {
137→      if (command.name === "clear") {
138→        onClearHistory?.();
139→      }
140→      return;
141→    }
142→
143→    const commandText = `/${command.name}`;
144→    if (isActive) {
145→      onSendMessage(commandText);
146→    } else {
147→      onSpawnAgent(commandText);
148→    }
149→  }
150→
151→  return (
152→    <div className="flex h-full flex-col">
153→      <StatusBar
154→        connected={connected}
155→        status={status}
156→        showRaw={showRaw}
