  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→  Workspace,
 65→} from "@/lib/types";
 66→
 67→/** Connect to the WS server on the same host the page was loaded from. */
 68→const WS_URL =
 69→  typeof window !== "undefined"
 70→    ? `ws://${window.location.hostname}:9900/browser`
 71→    : "ws://localhost:9900/browser";
 72→
 73→/** Per-agent client state. */
 74→export interface AgentClientState {
 75→  status: AgentStatus;
 76→  messages: ChatMessage[];
 77→  /** Raw Claude NDJSON messages for debug view. */
 78→  rawMessages: ClaudeMessage[];
 79→  label: string;
 80→  tmuxSession: string | null;
 81→  createdAt: number;
 82→}
 83→
 84→/**
 85→ * Extract displayable text from a Claude assistant message.
 86→ * Content blocks may be text, tool_use, or tool_result — each is
 87→ * handled defensively since the array structure can vary.
 88→ */
 89→function extractText(msg: ClaudeAssistant): string {
 90→  const blocks = msg.message?.content;
 91→  if (!blocks || !Array.isArray(blocks)) return "";
 92→  return blocks
 93→    .map((b) => {
 94→      if (b.type === "text") return b.text;
 95→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 96→      if (b.type === "tool_result") {
 97→        const c = (b as { content?: unknown }).content;
 98→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 99→      }
100→      return "";
101→    })
102→    .filter(Boolean)
103→    .join("\n");
104→}
105→
106→/** Module-level counter for generating unique message IDs. */
107→let msgCounter = 0;
108→function nextId() {
109→  return `msg-${Date.now()}-${++msgCounter}`;
110→}
111→
112→/**
113→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
114→ * Used both for live messages and for replaying message_history.
115→ */
116→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
117→  if (relayMsg.type === "relay") {
118→    const msg = relayMsg.message;
119→
120→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
121→      const init = msg as ClaudeSystemInit;
122→      return {
123→        id: nextId(),
124→        role: "system",
125→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
126→        timestamp: Date.now(),
127→      };
128→    }
129→
130→    if (msg.type === "user") {
131→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
132→      // Only render human-typed user messages (string content).
133→      // CLI tool_result messages have array content — these are internal
134→      // protocol messages and are only visible in the raw message viewer.
135→      if (typeof rawContent !== "string") return null;
136→      if (!rawContent.trim()) return null;
137→      return {
138→        id: nextId(),
139→        role: "user",
140→        content: rawContent,
141→        timestamp: Date.now(),
142→      };
143→    }
144→
145→    if (msg.type === "assistant") {
146→      const assistant = msg as ClaudeAssistant;
147→      const text = extractText(assistant);
148→      if (!text) return null;
149→
150→      const blocks = assistant.message?.content ?? [];
151→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
152→
153→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
154→      const resultMap = new Map<string, string>();
155→      for (const b of blocks) {
156→        if (b.type === "tool_result") {
157→          const tr = b as { tool_use_id?: string; content?: unknown };
158→          if (tr.tool_use_id) {
159→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
160→            const firstLine = raw.split("\n")[0];
161→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
162→          }
163→        }
164→      }
165→
166→      const toolCalls: ToolCallInfo[] = blocks
167→        .filter((b) => b.type === "tool_use")
168→        .map((b) => ({
169→          name: (b as { name: string }).name,
170→          toolUseId: (b as { id: string }).id,
171→          resultPreview: resultMap.get((b as { id: string }).id),
172→        }));
173→      const isToolOnly = !hasText && toolCalls.length > 0;
174→
175→      return {
176→        id: nextId(),
177→        role: "assistant",
178→        content: text,
179→        timestamp: Date.now(),
180→        toolCalls,
181→        isToolOnly,
182→      };
183→    }
184→
185→    if (msg.type === "result") {
186→      const result = msg as ClaudeResult;
187→      const summary = result.is_error
188→        ? `Error: ${result.error}`
189→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
190→      return {
191→        id: nextId(),
192→        role: "system",
193→        content: summary,
194→        timestamp: Date.now(),
195→      };
196→    }
197→
198→    if (msg.type === "control_request") {
199→      const cr = msg as ClaudeControlRequest;
200→
201→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
202→      if (cr.request.tool_name === "AskUserQuestion") {
203→        const input = cr.request.input as { questions?: UserQuestion[] };
204→        const questions = Array.isArray(input.questions) ? input.questions : [];
205→        return {
206→          id: nextId(),
207→          role: "system",
208→          content: "Question from Claude",
209→          timestamp: Date.now(),
210→          userQuestion: {
211→            requestId: cr.request_id,
212→            questions,
213→          },
214→        };
215→      }
216→
217→      return {
218→        id: nextId(),
219→        role: "system",
220→        content: `Tool approval requested: ${cr.request.tool_name}`,
221→        timestamp: Date.now(),
222→        controlRequest: {
223→          id: cr.request_id,
224→          tool_name: cr.request.tool_name,
225→          input: cr.request.input,
226→          description: cr.request.description,
227→        },
228→      };
229→    }
230→  }
231→
232→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
233→    return {
234→      id: nextId(),
235→      role: "system",
236→      content: `Error: ${relayMsg.error}`,
237→      timestamp: Date.now(),
238→    };
239→  }
240→
241→  return null;
242→}
243→
244→/** Console logger with [thos] prefix for easy filtering. */
245→function log(...args: unknown[]) {
246→  console.log("[thos-ws]", ...args);
247→}
248→
249→export function useWebSocket() {
250→  const wsRef = useRef<WebSocket | null>(null);
251→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
252→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
253→  const closingRef = useRef(false);
254→  const [connected, setConnected] = useState(false);
255→  /** True once we've received the initial agent_list from the server. */
256→  const [initialLoadDone, setInitialLoadDone] = useState(false);
257→
258→  // Multi-agent state
259→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
260→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
261→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
262→
263→  // Task state
264→  const [tasks, setTasks] = useState<Task[]>([]);
265→
266→  // Workspace state
267→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
268→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
269→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
270→
271→  // Per-agent deduplication: track count of processed messages per agent
272→  // to avoid duplicating messages already in local state during history replay.
273→  const processedCountRef = useRef<Map<string, number>>(new Map());
274→
275→  // Track which agents have had their history loaded (lazy loading).
276→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
277→
278→  /** Immutably update a single agent's state in the Map. */
279→  const updateAgent = useCallback(
280→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
281→      setAgents((prev) => {
282→        const existing = prev.get(agentId);
283→        if (!existing) return prev;
284→        const next = new Map(prev);
285→        next.set(agentId, updater(existing));
286→        return next;
287→      });
288→    },
289→    []
290→  );
291→
292→  const connect = useCallback(() => {
293→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
294→    if (wsRef.current) {
295→      wsRef.current.close();
296→      wsRef.current = null;
297→    }
298→
299→    // Reset dedup counts on new connection — server will send fresh history
300→    processedCountRef.current.clear();
301→    setInitialLoadDone(false);
302→    setLoadedAgents(new Set());
303→
304→    log("connecting to", WS_URL);
305→    const ws = new WebSocket(WS_URL);
306→    wsRef.current = ws;
307→
308→    ws.onopen = () => {
309→      log("connected");
310→      setConnected(true);
311→    };
312→
313→    ws.onclose = () => {
314→      log("disconnected, closingRef =", closingRef.current);
315→      setConnected(false);
316→      wsRef.current = null;
317→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
318→      if (closingRef.current) return;
319→      // Reconnection guard: clear any existing timer before scheduling
320→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
321→      log("scheduling reconnect in 2s");
322→      reconnectTimer.current = setTimeout(() => connect(), 2000);
323→    };
324→
325→    ws.onerror = (e) => {
326→      log("error", e);
327→      // onclose will fire after onerror, which triggers reconnect
328→    };
329→
330→    ws.onmessage = (event) => {
331→      let data: ServerMessage;
332→      try {
333→        data = JSON.parse(event.data as string);
334→      } catch {
335→        return;
336→      }
337→
338→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
339→
340→      // ── workspace_list: full workspace list from server ──
341→      if (data.type === "workspace_list") {
342→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
343→        log("workspace_list:", wsList.length, "workspaces");
344→        setWorkspaces(wsList);
345→        return;
346→      }
347→
348→      // ── directory_listing: response to browse_directory ──
349→      if (data.type === "directory_listing") {
350→        const listing = data as { path: string; entries: DirectoryEntry[] };
351→        log("directory_listing:", listing.path, listing.entries.length, "entries");
352→        setDirectoryListing({ path: listing.path, entries: listing.entries });
353→        return;
354→      }
355→
356→      // ── task_list: full task list from server ──
357→      if (data.type === "task_list") {
358→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
359→        setTasks((data as ServerTaskList).tasks);
360→        return;
361→      }
362→
363→      // ── task_updated: single task changed ──
364→      if (data.type === "task_updated") {
365→        const updated = (data as ServerTaskUpdated).task;
366→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
367→        return;
368→      }
369→
370→      // ── task_deleted: remove task ──
371→      if (data.type === "task_deleted") {
372→        const deletedId = (data as ServerTaskDeleted).taskId;
373→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
374→        return;
375→      }
376→
377→      // ── message_history: replay full history from server ──
378→      if (data.type === "message_history") {
379→        const historyMsg = data as ServerMessageHistory;
380→        const agentId = historyMsg.agentId;
381→        const serverMessages = historyMsg.messages;
382→        log("message_history:", agentId, serverMessages.length, "raw msgs");
383→
384→        // Convert all server messages to ChatMessages + extract raw Claude messages
385→        const chatMessages: ChatMessage[] = [];
386→        const rawMessages: ClaudeMessage[] = [];
387→        for (const sm of serverMessages) {
388→          if (sm.type === "relay") {
389→            rawMessages.push(sm.message);
390→          }
391→          const cm = relayChatMessage(agentId, sm);
392→          if (cm) chatMessages.push(cm);
393→        }
394→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
395→
396→        // Always replace local messages with server history (source of truth).
397→        setAgents((prev) => {
398→          const existing = prev.get(agentId);
399→          if (!existing) {
400→            log("message_history:", agentId, "agent not in map yet, creating");
401→            const next = new Map(prev);
402→            next.set(agentId, {
403→              status: "idle",
404→              messages: chatMessages,
405→              rawMessages,
406→              label: "",
407→              tmuxSession: null,
408→              createdAt: 0,
409→            });
410→            return next;
411→          }
412→          const next = new Map(prev);
413→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
414→          return next;
415→        });
416→
417→        processedCountRef.current.set(agentId, chatMessages.length);
418→        setLoadedAgents((prev) => {
419→          if (prev.has(agentId)) return prev;
420→          const next = new Set(prev);
421→          next.add(agentId);
422→          return next;
423→        });
424→        return;
425→      }
426→
427→      // ── history_cleared: wipe local messages for this agent ──
428→      if (data.type === "history_cleared") {
429→        updateAgent(data.agentId, (prev) => ({
430→          ...prev,
431→          messages: [],
432→          rawMessages: [],
433→        }));
434→        processedCountRef.current.set(data.agentId, 0);
435→        return;
436→      }
437→
438→      // ── cli_disconnected: show system message ──
439→      if (data.type === "cli_disconnected") {
440→        updateAgent(data.agentId, (prev) => ({
441→          ...prev,
442→          messages: [
443→            ...prev.messages,
444→            {
445→              id: nextId(),
446→              role: "system",
447→              content: "CLI session ended",
448→              timestamp: Date.now(),
449→            },
450→          ],
451→        }));
452→        return;
453→      }
454→
455→      // ── cli_connected: show system message ──
456→      if (data.type === "cli_connected") {
457→        updateAgent(data.agentId, (prev) => ({
458→          ...prev,
459→          messages: [
460→            ...prev.messages,
461→            {
462→              id: nextId(),
463→              role: "system",
464→              content: "CLI reconnected",
465→              timestamp: Date.now(),
466→            },
467→          ],
468→        }));
469→        return;
470→      }
471→
472→      // ── agent_list: reconcile sidebar state from server ──
473→      if (data.type === "agent_list") {
474→        const serverAgents = data.agents as AgentInfo[];
475→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
476→        setAgents((prev) => {
477→          const next = new Map(prev);
478→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
479→
480→          // Update or add agents from server
481→          for (const info of serverAgents) {
482→            const existing = next.get(info.agentId);
483→            if (existing) {
484→              next.set(info.agentId, {
485→                ...existing,
486→                status: info.status,
487→                tmuxSession: info.tmuxSession,
488→                label: info.label,
489→              });
490→            } else {
491→              next.set(info.agentId, {
492→                status: info.status,
493→                messages: [],
494→                rawMessages: [],
495→                label: info.label,
496→                tmuxSession: info.tmuxSession,
497→                createdAt: info.createdAt,
498→              });
499→            }
500→          }
501→
502→          // Remove agents no longer on the server
503→          for (const id of next.keys()) {
504→            if (!serverIds.has(id)) {
505→              next.delete(id);
506→            }
507→          }
508→
509→          return next;
510→        });
511→        setAgentOrder(serverAgents.map((a) => a.agentId));
512→        setInitialLoadDone(true);
513→
514→        // Auto-select the first agent on initial load when nothing is selected
515→        setActiveAgentId((prev) => {
516→          if (prev !== null) return prev;
517→          if (serverAgents.length === 0) return null;
518→          return serverAgents[0].agentId;
519→        });
520→        return;
521→      }
522→
523→      // ── spawned: auto-select the newly created agent ──
524→      if (data.type === "spawned") {
525→        setActiveAgentId(data.agentId);
526→        return;
527→      }
528→
529→      // ── status: update a specific agent's status ──
530→      if (data.type === "status") {
531→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
532→        return;
533→      }
534→
535→      // ── error: append to agent's message list ──
536→      if (data.type === "error") {
537→        updateAgent(data.agentId, (prev) => ({
538→          ...prev,
539→          messages: [
540→            ...prev.messages,
541→            {
542→              id: nextId(),
543→              role: "system",
544→              content: `Error: ${data.error}`,
545→              timestamp: Date.now(),
546→            },
547→          ],
548→        }));
549→        // Track processed count for dedup
550→        processedCountRef.current.set(
551→          data.agentId,
552→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
553→        );
554→        return;
555→      }
556→
557→      // ── relay: append claude message to agent's history ──
558→      if (data.type === "relay") {
559→        const agentId = data.agentId;
560→        const rawMsg = data.message;
561→        const chatMsg = relayChatMessage(agentId, data);
562→
563→        updateAgent(agentId, (prev) => ({
564→          ...prev,
565→          rawMessages: [...prev.rawMessages, rawMsg],
566→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
567→        }));
568→        if (chatMsg) {
569→          // Track processed count for dedup
570→          processedCountRef.current.set(
571→            agentId,
572→            (processedCountRef.current.get(agentId) ?? 0) + 1
573→          );
574→        }
575→        return;
576→      }
577→    };
578→  }, [updateAgent]);
579→
580→  useEffect(() => {
581→    closingRef.current = false;
582→    connect();
583→    return () => {
584→      closingRef.current = true;
585→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
586→      wsRef.current?.close();
587→    };
588→  }, [connect]);
589→
590→  const send = useCallback((data: object) => {
591→    if (wsRef.current?.readyState === WebSocket.OPEN) {
592→      wsRef.current.send(JSON.stringify(data));
593→    }
594→  }, []);
595→
596→  // Request history for the active agent if not already loaded.
597→  useEffect(() => {
598→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
599→    log("requesting history for", activeAgentId);
600→    send({ type: "request_history", agentId: activeAgentId });
601→  }, [activeAgentId, loadedAgents, send]);
602→
603→  const spawnAgent = useCallback(
604→    (prompt: string) => {
605→      send({ type: "spawn", prompt });
606→    },
607→    [send]
608→  );
609→
610→  const sendMessage = useCallback(
611→    (content: string) => {
612→      if (!activeAgentId) return;
613→      // Optimistically add user message to local state
614→      updateAgent(activeAgentId, (prev) => ({
615→        ...prev,
616→        messages: [
617→          ...prev.messages,
618→          {
619→            id: nextId(),
620→            role: "user",
621→            content,
622→            timestamp: Date.now(),
623→          },
624→        ],
625→      }));
626→      send({ type: "send_message", agentId: activeAgentId, content });
627→    },
628→    [send, activeAgentId, updateAgent]
629→  );
630→
631→  const respondToControl = useCallback(
632→    (requestId: string, allow: boolean) => {
633→      if (!activeAgentId) return;
634→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
635→      updateAgent(activeAgentId, (prev) => ({
636→        ...prev,
637→        messages: prev.messages.map((m) =>
638→          m.controlRequest?.id === requestId
639→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
640→            : m
641→        ),
642→      }));
643→    },
644→    [send, activeAgentId, updateAgent]
645→  );
646→
647→  /** Respond to an AskUserQuestion control request with the user's selections. */
648→  const respondToUserQuestion = useCallback(
649→    (requestId: string, answers: Record<string, string>) => {
650→      if (!activeAgentId) return;
651→      send({
652→        type: "control_response",
653→        agentId: activeAgentId,
654→        request_id: requestId,
655→        allow: true,
656→        answers,
657→      });
658→      updateAgent(activeAgentId, (prev) => ({
659→        ...prev,
660→        messages: prev.messages.map((m) =>
661→          m.userQuestion?.requestId === requestId
662→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
663→            : m
664→        ),
665→      }));
666→    },
667→    [send, activeAgentId, updateAgent]
668→  );
669→
670→  // ── Agent management actions ──────────────────────────────────────────────
671→
672→  const killAgent = useCallback(
673→    (agentId: string) => {
674→      send({ type: "kill_agent", agentId });
675→    },
676→    [send]
677→  );
678→
679→  const deleteAgent = useCallback(
680→    (agentId: string) => {
681→      send({ type: "delete_agent", agentId });
682→      // Deselect if we just deleted the active agent
683→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
684→    },
685→    [send]
686→  );
687→
688→  const renameAgent = useCallback(
689→    (agentId: string, label: string) => {
690→      send({ type: "rename_agent", agentId, label });
691→    },
692→    [send]
693→  );
694→
695→  const clearHistory = useCallback(
696→    (agentId: string) => {
697→      send({ type: "clear_history", agentId });
698→    },
699→    [send]
700→  );
701→
702→  // ── Task actions ──────────────────────────────────────────────────────────
703→
704→  const createTask = useCallback(
705→    (title: string, description: string, priority: TaskPriority) => {
706→      send({ type: "create_task", title, description, priority });
707→    },
708→    [send]
709→  );
710→
711→  const updateTask = useCallback(
712→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
713→      send({ type: "update_task", taskId, updates });
714→    },
715→    [send]
716→  );
717→
718→  const deleteTask = useCallback(
719→    (taskId: string) => {
720→      send({ type: "delete_task", taskId });
721→    },
722→    [send]
723→  );
724→
725→  const delegateTask = useCallback(
726→    (taskId: string) => {
727→      send({ type: "delegate_task", taskId });
728→    },
729→    [send]
730→  );
731→
732→  // ── Workspace actions ──────────────────────────────────────────────────────
733→
734→  const setActiveWorkspaceId = useCallback(
735→    (workspaceId: string | null) => {
736→      setActiveWorkspaceIdState(workspaceId);
737→      send({ type: "set_workspace", workspaceId });
738→    },
739→    [send]
740→  );
741→
742→  const createWorkspace = useCallback(
743→    (name: string, cwd: string) => {
744→      send({ type: "create_workspace", name, cwd });
745→    },
746→    [send]
747→  );
748→
749→  const renameWorkspace = useCallback(
750→    (workspaceId: string, name: string) => {
751→      send({ type: "rename_workspace", workspaceId, name });
752→    },
753→    [send]
754→  );
755→
756→  const deleteWorkspace = useCallback(
757→    (workspaceId: string) => {
758→      send({ type: "delete_workspace", workspaceId });
759→      setActiveWorkspaceIdState((prev) => (prev === workspaceId ? null : prev));
760→    },
761→    [send]
762→  );
763→
764→  const browseDirectory = useCallback(
765→    (path: string) => {
766→      send({ type: "browse_directory", path });
767→    },
768→    [send]
769→  );
770→
771→  // Derived values for the active agent
772→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
773→  const activeStatus = useMemo<AgentStatus>(
774→    () => activeAgent?.status ?? "idle",
775→    [activeAgent?.status]
776→  );
777→  const activeMessages = useMemo<ChatMessage[]>(
778→    () => activeAgent?.messages ?? [],
