780→  );
781→  const activeRawMessages = useMemo<ClaudeMessage[]>(
782→    () => activeAgent?.rawMessages ?? [],
783→    [activeAgent?.rawMessages]
784→  );
785→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
786→
787→  return {
788→    connected,
789→    initialLoadDone,
790→    historyLoading,
791→    agents,
792→    agentOrder,
793→    activeAgentId,
794→    setActiveAgentId,
795→    activeStatus,
796→    activeMessages,
797→    activeRawMessages,
798→    spawnAgent,
799→    sendMessage,
800→    respondToControl,
801→    respondToUserQuestion,
802→    killAgent,
803→    deleteAgent,
804→    renameAgent,
