457→
458→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
459→export type TaskPriority = "low" | "medium" | "high" | "urgent";
460→
461→/** A user-created task, optionally linked to a Claude agent. */
462→export interface Task {
463→  id: string;
464→  title: string;
465→  description: string;
466→  status: TaskStatus;
467→  priority: TaskPriority;
468→  /** If delegated, the agentId of the spawned Claude agent. */
469→  agentId: string | null;
470→  /** Workspace this task belongs to. */
471→  workspaceId: string | null;
472→  createdAt: number;
473→  updatedAt: number;
474→}
