  1→"use client";
  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { EllipsisVertical, Plus } from "lucide-react";
 17→import type { AgentStatus, Workspace } from "@/lib/types";
 18→import type { AgentClientState } from "@/hooks/use-websocket";
 19→import { cn } from "@/lib/utils";
 20→import { WorkspaceSwitcher } from "./workspace-switcher";
 21→
 22→/** Status dot color + optional pulse animation. */
 23→const STATUS_DOT: Record<AgentStatus, string> = {
 24→  idle: "bg-muted-foreground",
 25→  spawning: "bg-yellow-500 animate-pulse",
 26→  connected: "bg-green-500",
 27→  thinking: "bg-blue-500 animate-pulse",
 28→  done: "bg-muted-foreground",
 29→  disconnected: "bg-orange-500 animate-pulse",
 30→  error: "bg-red-500",
 31→};
 32→
 33→/** Statuses where the CLI is actively running and can be killed. */
 34→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 35→/** Statuses considered archived (session ended, read-only). */
 36→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 37→
 38→interface ContextMenuState {
 39→  agentId: string;
 40→  x: number;
 41→  y: number;
 42→}
 43→
 44→export function AgentSidebar({
 45→  agents,
 46→  agentOrder,
 47→  activeAgentId,
 48→  loading,
 49→  onSelect,
 50→  onNewAgent,
 51→  onKill,
 52→  onDelete,
 53→  onRename,
 54→  onClearHistory,
 55→  workspaces,
 56→  activeWorkspaceId,
 57→  onSelectWorkspace,
 58→  onRenameWorkspace,
 59→  onDeleteWorkspace,
 60→  onOpenFolder,
 61→}: {
 62→  agents: Map<string, AgentClientState>;
 63→  agentOrder: string[];
 64→  activeAgentId: string | null;
 65→  loading?: boolean;
 66→  onSelect: (agentId: string | null) => void;
 67→  onNewAgent: () => void;
 68→  onKill: (agentId: string) => void;
 69→  onDelete: (agentId: string) => void;
 70→  onRename: (agentId: string, label: string) => void;
 71→  onClearHistory: (agentId: string) => void;
 72→  workspaces: Workspace[];
 73→  activeWorkspaceId: string | null;
 74→  onSelectWorkspace: (workspaceId: string | null) => void;
 75→  onRenameWorkspace: (workspaceId: string, name: string) => void;
 76→  onDeleteWorkspace: (workspaceId: string) => void;
 77→  onOpenFolder: () => void;
 78→}) {
 79→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 80→  const [renamingId, setRenamingId] = useState<string | null>(null);
 81→  const menuRef = useRef<HTMLDivElement>(null);
 82→
 83→  // Split agents into active and archived
 84→  const activeIds = agentOrder.filter((id) => {
 85→    const a = agents.get(id);
 86→    return a && !ARCHIVED.has(a.status);
 87→  });
 88→  const archivedIds = agentOrder.filter((id) => {
 89→    const a = agents.get(id);
 90→    return a && ARCHIVED.has(a.status);
 91→  });
 92→
 93→  // Close context menu on click-outside or Escape
 94→  useEffect(() => {
 95→    if (!ctxMenu) return;
 96→    function handleClick(e: MouseEvent) {
 97→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
 98→        setCtxMenu(null);
 99→      }
100→    }
101→    function handleKey(e: KeyboardEvent) {
102→      if (e.key === "Escape") setCtxMenu(null);
103→    }
104→    document.addEventListener("mousedown", handleClick);
105→    document.addEventListener("keydown", handleKey);
106→    return () => {
107→      document.removeEventListener("mousedown", handleClick);
108→      document.removeEventListener("keydown", handleKey);
109→    };
110→  }, [ctxMenu]);
111→
112→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
113→    setCtxMenu({ agentId, x, y });
114→  }, []);
115→
116→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
117→    e.preventDefault();
118→    openMenu(agentId, e.clientX, e.clientY);
119→  }, [openMenu]);
120→
121→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
122→    e.stopPropagation();
123→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
124→    openMenu(agentId, rect.right, rect.bottom);
125→  }, [openMenu]);
126→
127→  const closeMenu = useCallback(() => setCtxMenu(null), []);
128→
129→  function renderAgentRow(id: string, archived: boolean) {
130→    const agent = agents.get(id);
131→    if (!agent) return null;
132→    const isActive = id === activeAgentId;
133→    return (
134→      <div
135→        key={id}
136→        onClick={() => onSelect(id)}
137→        onContextMenu={(e) => handleContextMenu(e, id)}
138→        className={cn(
139→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
140→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
141→          archived && "opacity-60"
142→        )}
143→      >
144→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
145→          <span className="flex items-center gap-2">
146→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
147→            {renamingId === id ? (
148→              <RenameInput
149→                initialValue={agent.label}
150→                onConfirm={(label) => {
151→                  onRename(id, label);
152→                  setRenamingId(null);
153→                }}
154→                onCancel={() => setRenamingId(null)}
155→              />
156→            ) : (
157→              <span className="truncate">{agent.label || "new agent"}</span>
158→            )}
159→          </span>
160→          {agent.tmuxSession && (
161→            <span className="pl-4 text-[10px] text-muted-foreground truncate">
162→              {agent.tmuxSession}
163→            </span>
164→          )}
165→        </div>
166→        <button
167→          onClick={(e) => handleMenuButton(e, id)}
168→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
169→          aria-label="Agent menu"
170→        >
171→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
172→        </button>
173→      </div>
174→    );
175→  }
176→
177→  return (
178→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
179→      {/* Workspace switcher */}
180→      <div className="border-b">
181→        <WorkspaceSwitcher
182→          workspaces={workspaces}
183→          activeWorkspaceId={activeWorkspaceId}
184→          onSelect={onSelectWorkspace}
185→          onRename={onRenameWorkspace}
186→          onDelete={onDeleteWorkspace}
187→          onOpenFolder={onOpenFolder}
188→        />
189→      </div>
190→
191→      {/* Header */}
192→      <div className="flex items-center justify-between px-3 py-2">
193→        <span className="text-xs font-semibold">agents</span>
194→        <button
195→          onClick={onNewAgent}
196→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
197→          aria-label="New agent"
198→        >
199→          <Plus className="size-3.5" />
200→        </button>
201→      </div>
202→
203→      {/* Agent list */}
204→      <div className="flex-1 overflow-y-auto">
205→        {loading ? (
206→          <div className="space-y-1 px-3 py-2">
207→            {[...Array(4)].map((_, i) => (
208→              <div key={i} className="flex items-center gap-2 py-2">
209→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
210→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
211→              </div>
212→            ))}
213→          </div>
214→        ) : agentOrder.length === 0 ? (
215→          <div className="px-3 py-4 text-xs text-muted-foreground">
216→            No agents yet
217→          </div>
218→        ) : null}
219→
220→        {/* Active agents */}
221→        {activeIds.map((id) => renderAgentRow(id, false))}
222→
223→        {/* Archived divider + agents */}
224→        {archivedIds.length > 0 && (
225→          <>
226→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
227→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
228→              <div className="flex-1 border-t" />
229→            </div>
230→            {archivedIds.map((id) => renderAgentRow(id, true))}
231→          </>
232→        )}
233→      </div>
234→
235→      {/* Context menu */}
236→      {ctxMenu && (() => {
237→        const agent = agents.get(ctxMenu.agentId);
238→        if (!agent) return null;
239→        return (
240→          <div
241→            ref={menuRef}
242→            className="fixed z-50 min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
243→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
244→          >
245→            <ContextMenuItem
246→              label="Rename"
247→              onClick={() => {
248→                setRenamingId(ctxMenu.agentId);
249→                closeMenu();
250→              }}
251→            />
252→            {KILLABLE.has(agent.status) && (
253→              <ContextMenuItem
254→                label="Kill"
255→                onClick={() => {
256→                  onKill(ctxMenu.agentId);
257→                  closeMenu();
258→                }}
259→              />
260→            )}
261→            <ContextMenuItem
262→              label="Clear History"
263→              onClick={() => {
264→                onClearHistory(ctxMenu.agentId);
265→                closeMenu();
266→              }}
267→            />
268→            <div className="my-1 border-t" />
269→            <ContextMenuItem
270→              label="Delete"
271→              destructive
272→              onClick={() => {
273→                closeMenu();
274→                if (confirm("Delete this agent? This cannot be undone.")) {
275→                  onDelete(ctxMenu.agentId);
276→                }
277→              }}
278→            />
279→          </div>
280→        );
281→      })()}
282→    </div>
283→  );
284→}
285→
286→/** A single item in the context menu. */
287→function ContextMenuItem({
288→  label,
289→  onClick,
290→  destructive,
291→}: {
292→  label: string;
293→  onClick: () => void;
294→  destructive?: boolean;
295→}) {
296→  return (
297→    <button
298→      onClick={onClick}
299→      className={cn(
300→        "flex w-full px-3 py-1.5 text-xs transition-colors",
301→        destructive
302→          ? "text-red-500 hover:bg-red-500/10"
303→          : "hover:bg-accent"
304→      )}
305→    >
306→      {label}
307→    </button>
308→  );
309→}
310→
311→/** Inline input for renaming an agent. */
312→function RenameInput({
313→  initialValue,
314→  onConfirm,
315→  onCancel,
316→}: {
317→  initialValue: string;
318→  onConfirm: (value: string) => void;
319→  onCancel: () => void;
320→}) {
321→  const [value, setValue] = useState(initialValue);
322→  const inputRef = useRef<HTMLInputElement>(null);
323→
324→  useEffect(() => {
325→    inputRef.current?.focus();
326→    inputRef.current?.select();
327→  }, []);
328→
329→  function handleKeyDown(e: React.KeyboardEvent) {
330→    e.stopPropagation();
331→    if (e.key === "Enter") {
332→      const trimmed = value.trim();
333→      if (trimmed) onConfirm(trimmed);
334→      else onCancel();
335→    } else if (e.key === "Escape") {
336→      onCancel();
337→    }
338→  }
339→
340→  return (
341→    <input
342→      ref={inputRef}
343→      type="text"
344→      value={value}
345→      onChange={(e) => setValue(e.target.value)}
346→      onKeyDown={handleKeyDown}
347→      onBlur={() => {
348→        const trimmed = value.trim();
349→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
350→        else onCancel();
351→      }}
352→      onClick={(e) => e.stopPropagation()}
353→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
354→    />
355→  );
356→}
