276→/** Badge color per Claude NDJSON message type. */
277→const TYPE_COLORS: Record<string, string> = {
278→  system: "text-yellow-500",
279→  assistant: "text-blue-400",
280→  result: "text-green-500",
281→  control_request: "text-orange-400",
282→  keep_alive: "text-muted-foreground",
283→};
284→
285→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
286→  const [expanded, setExpanded] = useState(false);
287→  const subtype = (message as { subtype?: string }).subtype;
288→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
289→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
290→
291→  return (
292→    <div className="font-mono text-[11px] leading-relaxed">
293→      <button
294→        onClick={() => setExpanded((v) => !v)}
295→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
296→      >
297→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
298→        <span className={colorClass}>{typeLabel}</span>
299→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
300→      </button>
301→      {expanded && (
302→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
303→          {JSON.stringify(message, null, 2)}
304→        </pre>
305→      )}
306→    </div>
307→  );
308→}
