  1→/**
  2→ * Sound effects module for thos.
  3→ *
  4→ * Maps agent events and tool types to sound pools. Each pool has
  5→ * multiple variants — a random one is picked on each play to keep
  6→ * it stimulating. Uses the Web Audio API via soundcn's sound engine.
  7→ */
  8→
  9→import { playSound } from "@/lib/sound-engine";
 10→import type { SoundAsset } from "@/lib/sound-types";
 11→
 12→// ── Impact sounds (Write / Edit / MultiEdit) ─────────────────────────
 13→import { impactGenericLight000Sound } from "@/lib/impact-generic-light-000";
 14→import { impactGenericLight001Sound } from "@/lib/impact-generic-light-001";
 15→import { impactGenericLight002Sound } from "@/lib/impact-generic-light-002";
 16→import { impactGenericLight003Sound } from "@/lib/impact-generic-light-003";
 17→import { impactGenericLight004Sound } from "@/lib/impact-generic-light-004";
