 20→import { clickSoftSound } from "@/lib/click-soft";
 21→import { click001Sound } from "@/lib/click-001";
 22→import { click002Sound } from "@/lib/click-002";
 23→import { click003Sound } from "@/lib/click-003";
 24→import { click004Sound } from "@/lib/click-004";
