 26→// ── Computer noise (Bash) ────────────────────────────────────────────
 27→import { computerNoise000Sound } from "@/lib/computer-noise-000";
 28→import { computerNoise001Sound } from "@/lib/computer-noise-001";
 29→import { computerNoise002Sound } from "@/lib/computer-noise-002";
 30→import { computerNoise003Sound } from "@/lib/computer-noise-003";
 31→
 32→// ── Tick sounds (Grep / Glob / search tools) ─────────────────────────
 33→import { tick001Sound } from "@/lib/tick-001";
 34→import { tick002Sound } from "@/lib/tick-002";
 35→import { tick004Sound } from "@/lib/tick-004";
 36→
 37→// ── Confirmation sounds (task result / done) ─────────────────────────
 38→import { confirmation001Sound } from "@/lib/confirmation-001";
 39→import { confirmation002Sound } from "@/lib/confirmation-002";
 40→import { confirmation003Sound } from "@/lib/confirmation-003";
 41→import { confirmation004Sound } from "@/lib/confirmation-004";
 42→
 43→// ── Error sounds ─────────────────────────────────────────────────────
 44→import { error001Sound } from "@/lib/error-001";
 45→import { error002Sound } from "@/lib/error-002";
 46→import { error003Sound } from "@/lib/error-003";
 47→
 48→// ── Question sounds (control requests / user prompts) ────────────────
 49→import { question001Sound } from "@/lib/question-001";
 50→import { question002Sound } from "@/lib/question-002";
 51→import { question003Sound } from "@/lib/question-003";
 52→
 53→// ── Session lifecycle ────────────────────────────────────────────────
 54→import { beginSound } from "@/lib/begin";
 55→import { powerUp1Sound } from "@/lib/power-up-1";
 56→
 57→// ── Sound pools ──────────────────────────────────────────────────────
 58→
 59→const POOLS = {
 60→  /** Write, Edit, MultiEdit — percussive impact */
 61→  codeWrite: [
 62→    impactGenericLight000Sound,
 63→    impactGenericLight001Sound,
 64→    impactGenericLight002Sound,
 65→    impactGenericLight003Sound,
 66→    impactGenericLight004Sound,
 67→  ],
 68→  /** Read — soft click */
 69→  codeRead: [
 70→    clickSoftSound,
 71→    click001Sound,
 72→    click002Sound,
 73→    click003Sound,
 74→    click004Sound,
 75→  ],
 76→  /** Bash — electronic/computer */
 77→  bash: [
 78→    computerNoise000Sound,
 79→    computerNoise001Sound,
 80→    computerNoise002Sound,
 81→    computerNoise003Sound,
 82→  ],
 83→  /** Grep, Glob, search — tick */
 84→  search: [
 85→    tick001Sound,
 86→    tick002Sound,
 87→    tick004Sound,
 88→  ],
 89→  /** Task result (success) */
 90→  done: [
 91→    confirmation001Sound,
 92→    confirmation002Sound,
 93→    confirmation003Sound,
 94→    confirmation004Sound,
 95→  ],
 96→  /** Errors */
 97→  error: [
 98→    error001Sound,
 99→    error002Sound,
100→    error003Sound,
101→  ],
102→  /** Control requests / questions */
103→  question: [
104→    question001Sound,
105→    question002Sound,
106→    question003Sound,
107→  ],
108→  /** Session start */
109→  begin: [
110→    beginSound,
111→    powerUp1Sound,
112→  ],
113→} as const;
114→
115→// ── Tool → pool mapping ──────────────────────────────────────────────
116→
117→const TOOL_POOL: Record<string, readonly SoundAsset[]> = {
118→  Write: POOLS.codeWrite,
