  codeRead: [
    clickSoftSound,
    click001Sound,
    click002Sound,
    click003Sound,
    click004Sound,
  ],
  bash: [
    glitch001Sound,
    glitch002Sound,
    glitch003Sound,
    glitch004Sound,
  ],
  search: [
    tick001Sound,
    tick002Sound,
    tick004Sound,
  ],
  done: [
    confirmation001Sound,
    confirmation002Sound,
    confirmation003Sound,
    confirmation004Sound,
  ],
  error: [
    error001Sound,
    error002Sound,
    error003Sound,
  ],
  question: [
    question001Sound,
    question002Sound,
    question003Sound,
